// Probe driver: runs the pre-compiled Python executable as a black box.
// Use JS \u escapes for control characters -- never literal control bytes.
import { execFileSync } from 'node:child_process';

export const EXE = '/workspace/dataset/test1_executable';

// Run with the two normal --a/--b args. Returns {out, err, code}.
export function run(a, b) {
  return raw(['--a', a, '--b', b]);
}

// Run with a fully custom argv list.
export function raw(argv) {
  try {
    const out = execFileSync(EXE, argv, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { out, err: '', code: 0 };
  } catch (e) {
    return { out: e.stdout ?? '', err: e.stderr ?? String(e.message), code: e.status ?? -1 };
  }
}

// Extract the old_value repr fragment for a single-char probe: run(s, MARKER)
export function reprOf(s) {
  const r = run(s, 'MARKER');
  const m = /'old_value': (.*)\}\}\}\n?$/s.exec(r.out);
  return m ? m[1] : `<<UNPARSED ${JSON.stringify(r.out)} ${JSON.stringify(r.err)}>>`;
}

