// Pin down difflib.unified_diff context grouping + hunk header rules.
import { run } from './drv.mjs';

const L = (n, tag) => Array.from({ length: n }, (_, i) => `${tag}${i}`);

function show(label, a, b) {
  const r = run(a, b);
  const m = /'diff': (.*)\}\}\}\n?$/s.exec(r.out);
  console.log(label.padEnd(34), m ? m[1] : `NO-DIFF-KEY ${JSON.stringify(r.out.trim())}`);
}

// 1) How many identical lines between two changes before the hunk splits?
for (let gap = 0; gap <= 9; gap++) {
  const mid = L(gap, 'm');
  const a = ['X', ...mid, 'Y'].join('\n');
  const b = ['X2', ...mid, 'Y2'].join('\n');
  show(`gap=${gap}`, a, b);
}

console.log('\n--- hunk header len 0/1 rules ---');
show('del-only-first-line', 'a\nb\nc', 'b\nc');
show('add-at-front', 'b\nc', 'a\nb\nc');
show('single-line-both', 'a\nb', 'a\nc');
show('empty-b', 'a\nb', '');
show('empty-a-vs-2', '', 'a\nb');
show('one-line-a-vs-empty', '\n', '');

console.log('\n--- blank line rendering ---');
show('blank-context', 'a\n\nb\nq', 'a\n\nb\nz');
show('blank-removed', 'a\n\nb', 'a\nb');

