/**
 * Unicode "printability" as CPython defines it for repr().
 *
 * CPython escapes a character in repr() when it is *not* printable, and
 * defines non-printable as: General_Category in
 *     Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs
 * with the single exception that ASCII space (U+0020) is printable.
 *
 * Node's regular-expression Unicode property escapes give us exactly those
 * groups with zero external dependencies:
 *     \p{C} = Cc + Cf + Cs + Co + Cn
 *     \p{Z} = Zs + Zl + Zp
 */

const NON_PRINTABLE = /[\p{C}\p{Z}]/u;

const SPACE = 0x20;

/**
 * Code points where this build of Node disagrees with the CPython build's
 * Unicode database. Populated only from confirmed differential evidence;
 * `true` means "CPython considers it printable", `false` means "CPython
 * escapes it". Kept as an explicit table so the override is auditable.
 */
const OVERRIDES = new Map();

/** Is this code point printable according to CPython's repr() rules? */
export function isPrintableCodePoint(cp) {
  const override = OVERRIDES.get(cp);
  if (override !== undefined) return override;
  if (cp === SPACE) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

/** Same test, given a single-code-point string. */
export function isPrintableChar(ch) {
  return isPrintableCodePoint(ch.codePointAt(0));
}

/** Python's str.isprintable(): true when every code point is printable. */
export function isPrintable(s) {
  for (const ch of s) {
    if (!isPrintableChar(ch)) return false;
  }
  return true;
}

