input.content:
/**
 * CPython's repr() for str objects, reproduced exactly.
 *
 * Mirrors unicode_repr() in Objects/unicodeobject.c: the quote character is
 * chosen first, then each *code point* is emitted through an ordered chain of
 * branches. The branch order matters -- backslash and the active quote are
 * handled before the whitespace shorthands, and the ASCII fast paths run
 * before any Unicode category lookup.
 */

import { isPrintableCodePoint } from './printable.mjs';

const HEX = '0123456789abcdef';

function hex(cp, width) {
  let out = '';
  for (let shift = (width - 1) * 4; shift >= 0; shift -= 4) {
    out += HEX[(cp >> shift) & 0xf];
  }
  return out;
}

/**
 * Pick the enclosing quote the way CPython does: a single quote unless the
 * string contains a single quote and no double quote.
 */
export function chooseQuote(s) {
  return s.includes("'") && !s.includes('"') ? '"' : "'";
}

/**
 * repr() of a Python str.
 *
 * Iterating with for..of walks code points, so astral characters are handled
 * as one unit (never as a UTF-16 surrogate pair) -- which is what CPython
 * sees. Lone surrogates, which reach us from argv via surrogateescape, are
 * themselves code points in category Cs and so come out as \udcXX.
 */
export function reprStr(s) {
  const quote = chooseQuote(s);
  let out = quote;

  for (const ch of s) {
    const cp = ch.codePointAt(0);

    // Escape the active quote and the backslash.
    if (ch === quote || cp === 0x5c /* \ */) {
      out += '\\' + ch;
      continue;
    }

    // Special whitespace shorthands. Note that CPython has shorthands for
    // exactly these three -- \a \b \v \f are *not* used, they fall through
    // to the \xHH form below.
    if (cp === 0x09) { out += '\\t'; continue; }
    if (cp === 0x0a) { out += '\\n'; continue; }
    if (cp === 0x0d) { out += '\\r'; continue; }

    // Non-printable US-ASCII.
    if (cp < 0x20 || cp === 0x7f) {
      out += '\\x' + hex(cp, 2);
      continue;
    }

    // Printable US-ASCII passes through untouched.
    if (cp < 0x7f) {
      out += ch;
      continue;
    }

    // Non-ASCII: escape only what the Unicode database calls non-printable.
    if (isPrintableCodePoint(cp)) {
      out += ch;
    } else if (cp <= 0xff) {
      out += '\\x' + hex(cp, 2);
    } else if (cp <= 0xffff) {
      out += '\\u' + hex(cp, 4);
    } else {
      out += '\\U' + hex(cp, 8);
    }
  }

  return out + quote;
}

