/**
 * The line boundaries recognised by str.splitlines(). This is a wider set
 * than "\n": it also includes the vertical tab, form feed, the three ASCII
 * information separators, NEL, and the Unicode line/paragraph separators.
 */
const LINE_BOUNDARIES = new Set([
  0x0a, // \n  line feed
  0x0b, // \v  vertical tab
  0x0c, // \f  form feed
  0x0d, // \r  carriage return
  0x1c, //     file separator
  0x1d, //     group separator
  0x1e, //     record separator
  0x85, //     next line (NEL)
  0x2028, //   line separator
  0x2029, //   paragraph separator
]);

export function isLineBoundary(cp) {
  return LINE_BOUNDARIES.has(cp);
}

/**
 * Python's str.splitlines() with keepends=False.
 *
 * Terminators are dropped, "\r\n" counts as a single boundary, and a trailing
 * boundary does not produce a final empty element -- so 'a\n' yields ['a']
 * while 'a\n\n' yields ['a', ''].
 *
 * Indexing is by UTF-16 code unit, which is safe here because every boundary
 * character is in the BMP: the halves of a surrogate pair can never be
 * mistaken for one.
 */
export function splitLines(s) {
  const lines = [];
  const n = s.length;
  let start = 0;
  let i = 0;

  while (i < n) {
    const cp = s.charCodeAt(i);
    if (!LINE_BOUNDARIES.has(cp)) {
      i += 1;
      continue;
    }
    lines.push(s.slice(start, i));
    // Treat CRLF as one boundary.
    i += cp === 0x0d && i + 1 < n && s.charCodeAt(i + 1) === 0x0a ? 2 : 1;
    start = i;
  }

  if (start < n) lines.push(s.slice(start));
  return lines;
}

