  /**
   * @param {(el: string) => boolean | null} isjunk
   * @param {string[]} a
   * @param {string[]} b
   * @param {boolean} autojunk
   */
  constructor(isjunk = null, a = [], b = [], autojunk = true) {
    this.isjunk = isjunk;
    this.a = a;
    this.b = b;
    this.autojunk = autojunk;
    this.matchingBlocks = null;
    this.opcodes = null;
    this.#chainB();
  }

