      const indices = b2j.get(el);
      if (indices === undefined) b2j.set(el, [i]);
      else indices.push(i);
    }

    this.bjunk = new Set();
    if (this.isjunk) {
      for (const el of b2j.keys()) {
        if (this.isjunk(el)) this.bjunk.add(el);
      }
      for (const el of this.bjunk) b2j.delete(el);
    }

    this.bpopular = new Set();
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [el, idxs] of b2j) {
        if (idxs.length > ntest) this.bpopular.add(el);
      }
      for (const el of this.bpopular) b2j.delete(el);
