/**
 * difflib.unified_diff.
 */

import { SequenceMatcher } from './sequencematcher.mjs';

/**
 * Render one side of a hunk header.
 *
 * A one-line range prints as a bare line number with no length, and an empty
 * range prints as the line *before* the range with a zero length -- which is
 * where the "-1 +0,0" style headers come from.
 */
function formatRangeUnified(start, stop) {
  let beginning = start + 1; // line numbers are 1-based
  const length = stop - start;
  if (length === 1) return String(beginning);
  if (length === 0) beginning -= 1;
  return `${beginning},${length}`;
}

/**
 * Unified diff of two line lists, returned as a list of output lines.
 *
 * With the default empty `lineterm`, no line carries a terminator, so the two
 * file headers are exactly "--- " and "+++ " -- a single trailing space each,
 * left over from the empty filename.
 */
export function unifiedDiff(a, b, { fromfile = '', tofile = '', fromfiledate = '', tofiledate = '', n = 3, lineterm = '' } = {}) {
  const out = [];
  let started = false;

  for (const group of new SequenceMatcher(null, a, b).getGroupedOpcodes(n)) {
    if (!started) {
      started = true;
      const fromdate = fromfiledate ? `\t${fromfiledate}` : '';
      const todate = tofiledate ? `\t${tofiledate}` : '';
      out.push(`--- ${fromfile}${fromdate}${lineterm}`);
      out.push(`+++ ${tofile}${todate}${lineterm}`);
    }

    const first = group[0];
    const last = group[group.length - 1];
    const range1 = formatRangeUnified(first.i1, last.i2);
    const range2 = formatRangeUnified(first.j1, last.j2);
    out.push(`@@ -${range1} +${range2} @@${lineterm}`);

    for (const { tag, i1, i2, j1, j2 } of group) {
      if (tag === 'equal') {
        for (const line of a.slice(i1, i2)) out.push(' ' + line);
        continue;
      }
      if (tag === 'replace' || tag === 'delete') {
        for (const line of a.slice(i1, i2)) out.push('-' + line);
      }
