/**
 * Recovering argv the way CPython sees it.
 *
 * CPython decodes command-line arguments as UTF-8 with the `surrogateescape`
 * error handler, so a byte that cannot be decoded survives as a lone surrogate
 * in the range U+DC80..U+DCFF and reprs as e.g. '\udcff'. Node instead decodes
 * argv as lossy UTF-8, turning those bytes into U+FFFD and destroying the
 * information.
 *
 * To stay faithful we read the raw bytes from /proc/self/cmdline and decode
 * them ourselves. Where that is unavailable we fall back to process.argv,
 * which is correct for every well-formed input.
 */

import { readFileSync } from 'node:fs';

// Allowed range for the second byte of a multi-byte sequence, keyed by lead
// byte. These ranges are what reject overlong encodings, encoded surrogates,
// and anything above U+10FFFF.
function secondByteRange(lead) {
  if (lead >= 0xc2 && lead <= 0xdf) return [0x80, 0xbf, 2];
  if (lead === 0xe0) return [0xa0, 0xbf, 3];
  if (lead >= 0xe1 && lead <= 0xec) return [0x80, 0xbf, 3];
  if (lead === 0xed) return [0x80, 0x9f, 3];
  if (lead >= 0xee && lead <= 0xef) return [0x80, 0xbf, 3];
  if (lead === 0xf0) return [0x90, 0xbf, 4];
  if (lead >= 0xf1 && lead <= 0xf3) return [0x80, 0xbf, 4];
  if (lead === 0xf4) return [0x80, 0x8f, 4];
  return null;
}

/**
 * Decode UTF-8 bytes with Python's `surrogateescape` handler: every byte that
 * is not part of a valid sequence becomes U+DC00 + byte.
 */
export function decodeSurrogateEscape(bytes) {
  let out = '';
  let i = 0;
  const n = bytes.length;

  while (i < n) {
    const lead = bytes[i];

    if (lead < 0x80) {
      out += String.fromCharCode(lead);
      i += 1;
      continue;
    }

    const range = secondByteRange(lead);
    if (range === null) {
      out += String.fromCharCode(0xdc00 + lead);
      i += 1;
      continue;
    }

    const [lo, hi, width] = range;
    let ok = i + width <= n && bytes[i + 1] >= lo && bytes[i + 1] <= hi;
    for (let k = 2; ok && k < width; k++) {
      ok = bytes[i + k] >= 0x80 && bytes[i + k] <= 0xbf;
    }
    if (!ok) {
      // Emit one escape and resume at the next byte; any stray continuation
      // bytes that follow are escaped on their own turn, which reproduces
      // CPython's per-byte replacement of the invalid span.
      out += String.fromCharCode(0xdc00 + lead);
      i += 1;
      continue;
    }

    let cp = lead & (width === 2 ? 0x1f : width === 3 ? 0x0f : 0x07);
    for (let k = 1; k < width; k++) cp = (cp << 6) | (bytes[i + k] & 0x3f);
    out += String.fromCodePoint(cp);
    i += width;
  }

  return out;
}

/**
 * The user-supplied arguments, i.e. everything after the script path.
 *
 * process.argv is [execPath, scriptPath, ...userArgs], so the count of user
 * arguments tells us how many trailing entries of /proc/self/cmdline to take
 * -- which sidesteps having to model how node lays out its own execArgv.
 */
export function getArgs() {
  const expected = process.argv.length - 2;
  if (expected <= 0) return [];

  try {
    const raw = readFileSync('/proc/self/cmdline');
    const parts = [];
    let start = 0;
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === 0) {
        parts.push(raw.subarray(start, i));
        start = i + 1;
      }
    }
    if (start < raw.length) parts.push(raw.subarray(start));

    if (parts.length >= expected) {
      return parts.slice(parts.length - expected).map(decodeSurrogateEscape);
    }
  } catch {
    // Fall through to the portable path.
  }

  return process.argv.slice(2);
}

/** Program name as CPython would derive it: basename of the script path. */
export function getProgName() {
  const path = process.argv[1] ?? '';
  const cut = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
  return cut === -1 ? path : path.slice(cut + 1);
}

