/**
 * Rendering Python values the way repr() does.
 */

import { reprStr } from './repr.mjs';

/**
 * repr() of a value built from strings and Maps.
 *
 * Maps stand in for dicts: JavaScript Maps preserve insertion order, which is
 * exactly the guarantee Python dicts give, so key order survives unchanged.
 */
export function reprValue(value) {
  if (typeof value === 'string') return reprStr(value);
  if (value instanceof Map) return reprDict(value);
  throw new TypeError(`no repr for ${typeof value}`);
}

/** repr() of a dict: `{}` when empty, otherwise `{k: v, k: v}`. */
export function reprDict(map) {
  if (map.size === 0) return '{}';
  const parts = [];
  for (const [key, value] of map) {
    parts.push(`${reprValue(key)}: ${reprValue(value)}`);
  }
  return `{${parts.join(', ')}}`;
}

