/**
 * The DeepDiff result container.
 *
 * DeepDiff's text-style result is a dict keyed by report kind, from which
 * empty kinds are dropped -- so two equal inputs give a bare `{}`. Each
 * `values_changed` entry is keyed by the path to the changed value and holds
 * `new_value` first, then `old_value`, then an optional `diff`.
 */

import { reprDict } from '../python/pprint.mjs';

export class TextResult {
  constructor() {
    this.tree = new Map();
  }

  /** Record a changed value at `path`; `diff` is omitted when absent. */
  addValuesChanged(path, oldValue, newValue, diff = null) {
    let bucket = this.tree.get('values_changed');
    if (bucket === undefined) {
      bucket = new Map();
      this.tree.set('values_changed', bucket);
    }
    const changed = new Map();
    changed.set('new_value', newValue);
    changed.set('old_value', oldValue);
    if (diff !== null) changed.set('diff', diff);
    bucket.set(path, changed);
  }

  toString() {
    return reprDict(this.tree);
  }
}

