/**
 * DeepDiff, restricted to the case this program can actually reach.
 *
 * argparse hands us `type=str` for both operands, so the only comparison
 * DeepDiff ever performs here is string-vs-string. That path reports at most a
 * single `values_changed` entry at the root, and never a type change.
 */

import { splitLines } from '../python/strings.mjs';
import { unifiedDiff } from '../difflib/unified.mjs';
import { TextResult } from './result.mjs';

const ROOT = 'root';

/**
 * The convenience `diff` field DeepDiff attaches to a changed string.
 *
 * The gate is a literal test for a newline in either operand -- not a test for
 * "more than one line". A string split by some other Python line boundary
 * (\r, \v,  , ...) but containing no \n gets no diff field at all, even
 * though its lines differ. Once the gate opens, splitting uses the full set of
 * Python line boundaries, and an empty diff (both sides split to the same
 * lines, as with 'a\n' vs 'a') leaves the field off.
 */
function stringDiff(t1, t2) {
  if (!t1.includes('\n') && !t2.includes('\n')) return null;
  const lines = unifiedDiff(splitLines(t1), splitLines(t2), { lineterm: '' });
  return lines.length ? lines.join('\n') : null;
}

/** Compare two strings and return the result container. */
export function DeepDiff(t1, t2) {
  const result = new TextResult();
  if (t1 === t2) return result;
  result.addValuesChanged(ROOT, t1, t2, stringDiff(t1, t2));
  return result;
}

