/**
 * Synchronous stdout/stderr writes.
 *
 * Writing through fs.writeSync rather than process.stdout.write guarantees the
 * bytes have left the process before an explicit exit -- process.stdout is
 * asynchronous when it points at a pipe, so buffered output can otherwise be
 * dropped when the parser exits with a status code.
 */

import { writeSync } from 'node:fs';

const STDOUT = 1;
const STDERR = 2;

function write(fd, text) {
  if (!text) return;
  const buf = Buffer.from(text, 'utf8');
  let off = 0;
  while (off < buf.length) {
    off += writeSync(fd, buf, off, buf.length - off);
  }
}

export function writeOut(text) {
  write(STDOUT, text);
}

export function writeErr(text) {
  write(STDERR, text);
}

