/**
 * A faithful subset of Python's argparse.
 *
 * Only what this program's parser can reach is modelled: store actions that
 * take exactly one value, plus the automatic -h/--help. There are no
 * positional actions, which collapses argparse's pattern-matching machinery
 * into a straightforward left-to-right walk -- but the *observable* behaviour
 * is preserved case for case: abbreviation matching, `--opt=value`, the
 * negative-number exemption, the `--` sentinel, extras collection, error
 * precedence, and the exact wording of every message.
 */

import { writeOut, writeErr } from './io.mjs';

const PREFIX_CHARS = '-';

/** argparse's _negative_number_matcher. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Thrown by an action to be reported as `argument <name>: <message>`. */
class ArgumentError extends Error {
  constructor(actionName, message) {
    super(`argument ${actionName}: ${message}`);
    this.actionName = actionName;
  }
}

/** Signals a call to parser.exit(); the caller decides how to terminate. */
export class ParserExit extends Error {
  constructor(status) {
    super(`exit ${status}`);
    this.status = status;
  }
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.allowAbbrev = true;
    this.addArgument(['-h', '--help'], {
      dest: 'help',
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, { dest, nargs = 1, required = false, help = null } = {}) {
    // The destination and metavar defaults argparse derives from the first
    // long option string: '--a' -> dest 'a', metavar 'A'.
    const primary = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const derived = primary.replace(/^-+/, '').replace(/-/g, '_');
    const action = {
      optionStrings,
      dest: dest ?? derived,
      metavar: derived.toUpperCase(),
      nargs,
      required,
      help,
    };
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  /** `--a` -- the name argparse uses when naming an action in a message. */
  #actionName(action) {
    return action.optionStrings.join('/');
  }

  formatUsage() {
    const parts = [];
    for (const action of this.actions) {
      const flag = action.optionStrings[0];
      const body = action.nargs === 0 ? flag : `${flag} ${action.metavar}`;
      parts.push(action.required ? body : `[${body}]`);
    }
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    // argparse lays the help column at min(maxInvocationLength + 2, 24),
    // measured with the two-space entry indent included.
    const invocations = this.actions.map((action) =>
      action.nargs === 0
        ? action.optionStrings.join(', ')
        : action.optionStrings.map((s) => `${s} ${action.metavar}`).join(', ')
    );
    const maxLength = Math.max(...invocations.map((s) => s.length + 2));
    const helpPosition = Math.min(maxLength + 2, 24);

    let out = `${this.formatUsage()}\noptions:\n`;
    for (let i = 0; i < this.actions.length; i++) {
      const invocation = invocations[i];
      const text = this.actions[i].help;
      if (!text) {
        out += `  ${invocation}\n`;
        continue;
      }
      const pad = ' '.repeat(Math.max(helpPosition - (invocation.length + 2), 2));
      out += `  ${invocation}${pad}${text}\n`;
    }
    return out;
  }

  printUsage() {
    writeOut(this.formatUsage());
  }

  printHelp() {
    writeOut(this.formatHelp());
  }

  exit(status = 0, message = '') {
    if (message) writeErr(message);
    throw new ParserExit(status);
  }

  /** Usage to stderr, then `prog: error: message`, then exit status 2. */
  error(message) {
    writeErr(this.formatUsage());
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  /**
   * argparse's _parse_optional: decide whether a token names an option.
   *
   * Returns null when the token is a value, or [action|null, optionString,
   * explicitArg] when it looks like an option -- a null action meaning "looks
   * like an option but no such option exists", which becomes an extra rather
   * than an error.
   */
  #parseOptional(argString) {
    if (!argString) return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    const exact = this.optionStringActions.get(argString);
    if (exact !== undefined) return [exact, argString, null];

    // A bare '-' is a value, not an option.
    if (argString.length === 1) return null;

    if (argString.includes('=')) {
      const idx = argString.indexOf('=');
      const optionString = argString.slice(0, idx);
      const action = this.optionStringActions.get(optionString);
      if (action !== undefined) return [action, optionString, argString.slice(idx + 1)];
    }

    const tuples = this.#getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (tuples.length === 1) {
      return tuples[0];
    }

    // Something like '-1' is a value: no registered option looks like a
    // negative number, so there is nothing for it to be confused with.
    if (NEGATIVE_NUMBER.test(argString)) return null;

    // A token containing a space was meant to be a value.
    if (argString.includes(' ')) return null;

    return [null, argString, null];
  }

