class ArgumentError extends Error {
  constructor(actionName, message) {
    super(`argument ${actionName}: ${message}`);
    this.actionName = actionName;
  }
}

/** Signals a call to parser.exit(); the caller decides how to terminate. */
export class ParserExit extends Error {
  constructor(status) {
    super(`exit ${status}`);
    this.status = status;
  }
}

