      const shortExplicitArg = optionString.slice(2);
      for (const [candidate, action] of this.optionStringActions) {
        if (candidate === shortOptionPrefix) {
          result.push([action, candidate, shortExplicitArg]);
        } else if (candidate.startsWith(optionPrefix)) {
          result.push([action, candidate, null]);
        }
      }
    }

    return result;
  }

  /**
   * Parse, returning [namespace, extras].
   *
   * The classification pass builds argparse's pattern string: 'O' for a token
   * that names an option, 'A' for a value, and '-' for the `--` sentinel,
   * after which everything is a value. Because an optional's nargs pattern has
