        pattern.push('-');
        afterSentinel = true;
        continue;
      }
      const tuple = this.#parseOptional(argStrings[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const namespace = Object.create(null);
    for (const action of this.actions) namespace[action.dest] = undefined;
    const extras = [];
    const seen = new Set();

    const consumeOptional = (startIndex) => {
      const [action, optionString, explicitArg] = optionTuples.get(startIndex);

      // Looks like an option but is not one: set it aside and move on.
      if (action === null) {
        extras.push(argStrings[startIndex]);
        return startIndex + 1;
      }

      seen.add(action);

      if (explicitArg !== null) {
        if (action.nargs === 1) {
          this.#takeAction(action, [explicitArg], namespace);
          return startIndex + 1;
        }
        // A flag given a value: argparse rejects the value outright.
        this.#fail(new ArgumentError(this.#actionName(action), `ignored explicit argument '${explicitArg}'`));
      }

      if (action.nargs === 0) {
        this.#takeAction(action, [], namespace);
        return startIndex + 1;
      }

      // One value, which must be a plain value: 'O' and '-' both fail here.
      if (pattern[startIndex + 1] !== 'A') {
        this.#fail(new ArgumentError(this.#actionName(action), 'expected one argument'));
      }
      this.#takeAction(action, [argStrings[startIndex + 1]], namespace);
      return startIndex + 2;
    };

    const optionIndices = [...optionTuples.keys()].sort((x, y) => x - y);
    let startIndex = 0;
    const maxOptionIndex = optionIndices.length ? optionIndices[optionIndices.length - 1] : -1;

    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = optionIndices.find((idx) => idx >= startIndex);
      if (nextOptionIndex === undefined) break;
      // With no positional actions, any run of values is unconsumable.
      if (startIndex !== nextOptionIndex) {
        extras.push(...argStrings.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(nextOptionIndex);
    }
    extras.push(...argStrings.slice(startIndex));

    const missing = this.actions.filter((a) => a.required && !seen.has(a));
    if (missing.length) {
