/**
 * Differential harness: run the same argv through the Python executable and
 * through /output/test1.mjs, and compare stdout, stderr and exit code exactly.
 *
 * The Python prog name is 'test1_executable' and the Node one is 'test1.mjs';
 * that single substitution is applied before comparing, since the program name
 * genuinely differs and everything else must match byte for byte.
 */
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test1_executable';
const SCRIPT = '/output/test1.mjs';

function invoke(cmd, args, argv) {
  try {
    const out = execFileSync(cmd, [...args, ...argv], {
      encoding: 'buffer',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return { out: out.toString('utf8'), err: '', code: 0 };
  } catch (e) {
    return {
      out: (e.stdout ?? Buffer.alloc(0)).toString('utf8'),
      err: (e.stderr ?? Buffer.alloc(0)).toString('utf8'),
      code: e.status ?? -1,
    };
  }
}

const normalise = (s) => s.split('test1_executable').join('test1.mjs');

export function compare(argv) {
  const py = invoke(EXE, [], argv);
  const js = invoke(process.execPath, [SCRIPT], argv);
  const expected = {
    out: normalise(py.out),
    err: normalise(py.err),
    code: py.code,
  };
  const ok = expected.out === js.out && expected.err === js.err && expected.code === js.code;
  return { ok, argv, expected, actual: js };
}

export function report(results, { label = 'cases', showPass = false } = {}) {
  let fails = 0;
  for (const r of results) {
    if (r.ok) {
      if (showPass) console.log(`PASS ${JSON.stringify(r.argv)}`);
      continue;
    }
    fails += 1;
    console.log(`FAIL ${JSON.stringify(r.argv)}`);
    if (r.expected.out !== r.actual.out) {
      console.log(`  py.out ${JSON.stringify(r.expected.out)}`);
      console.log(`  js.out ${JSON.stringify(r.actual.out)}`);
    }
    if (r.expected.err !== r.actual.err) {
      console.log(`  py.err ${JSON.stringify(r.expected.err)}`);
      console.log(`  js.err ${JSON.stringify(r.actual.err)}`);
    }
    if (r.expected.code !== r.actual.code) {
      console.log(`  code   py=${r.expected.code} js=${r.actual.code}`);
    }
  }
  console.log(`\n${label}: ${results.length - fails}/${results.length} match`);
  return fails;
}

